use vstd::prelude::*;

verus! {

fn swap(arr: &mut Vec<i32>, i: usize, j: usize)
    requires
        i < old(arr).len(),
        j < old(arr).len(),
    ensures
        arr.len() == old(arr).len(),
        arr[i as int] == old(arr)[j as int],
        arr[j as int] == old(arr)[i as int],
        forall|k: int|
            0 <= k < arr.len() && k != i as int && k != j as int
                ==> arr[k] == old(arr)[k],
{
    // Standard 3-step swap using a temporary.
    // Works even when i == j (then it writes the same value back).
    let tmp = arr[i];
    let vj = arr[j];

    arr.set(i, vj);
    arr.set(j, tmp);
}

} // verus!

